INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(151900, 0, 1519, 0, 0, 0, 'Stormwind City', 'Stormwind City is the capital of the human kingdom of Stormwind and the chief stronghold of the Alliance, raised in white stone on the northwest coast, north of Elwynn Forest. The old city was reduced to ashes when the orcish Horde sacked it in the First War and King Llane was slain. It rose again through the labor of the Stonemasons'' Guild, aided by the Church of the Holy Light and by King Terenas of Lordaeron. Canals now divide the city into districts: the busy Trade District, Cathedral Square beneath the Cathedral of Light, the poor streets of Old Town, the Mage Quarter, and the Dwarven District with its tram to Ironforge. The Stockade holds the kingdom''s prisoners, and Stormwind Keep, seat of the House of Wrynn, looks out over all of it.', 'warcraft.wiki.gg/wiki/Stormwind_City (founding, First War, rebuilding by Stonemasons, Church of Light and Terenas, districts, Deeprun Tram); quest 373 (City Hall, Cathedral Square); npc_text 13593 (Varian: reclaim my throne); quest 6403 description (Prestor is Onyxia); quest 13347 (Bolvar''s fall)'),
(151901, 1, 1519, 1, 0, 0, 'Valley of Heroes', 'The Valley of Heroes is the southern approach to Stormwind, where a stone bridge crosses the moat to the city gates. Along the road stand five statues of the leaders of the Alliance Expedition that marched through the Dark Portal into Draenor: Archmage Khadgar, General Turalyon, Ranger Captain Alleria Windrunner, Danath Trollbane and the gryphon rider Kurdran Wildhammer. Each plaque calls its hero presumed deceased and carries a farewell from a comrade or kinsman, from Antonidas and Uther to Sylvanas Windrunner. Field Marshal Afrasiabi and Major Mattingly keep watch here, and it is here that the Field Marshal proclaims the Alliance''s great victories to the gathered city.', 'warcraft.wiki.gg/wiki/Valley_of_Heroes (pre-Cataclysm: bridge, moat, five statues of the Alliance Expedition); gameobjects 25329-25333 and page_text 287-291 (plaques, presumed deceased, dedications); DB: Khadgar 18166, Force Commander Danath Trollbane 16819, Kurdran Wildhammer 21330 spawned on map 530 (Outland); DB spawns: Field Marshal Afrasiabi 14721, Major Mattingly 14394 by the gate; quest 7782 and creature_text 14721 (Nefarian slain, rally around your champion); tools/posarea.py: Afrasiabi, Mattingly, Marcus Jonathan, Jorgen and Squire Rowe spawns all resolve to area 1617'),
(151902, 1, 1519, 2, 0, 13, 'Stormwind Harbor', 'Stormwind Harbor spreads along the Great Sea below the city''s northwestern quarter, a fortified port of tiered docks, cannon emplacements and steam tanks, kept ready by the city''s cannoneers and engineers. Not every ship here sails for war. From one dock The Bravery travels back and forth between Stormwind and Auberdine in Darkshore, and night elf sentinels from that distant town keep watch over its berth, a sign of how far across the sea the kingdom''s friendships now reach.', 'warcraft.wiki.gg/wiki/Stormwind_Harbor (added 3.0.2, Scourge attack, Varian and Bolvar on the walls, Kraken and Bravery routes, cannons and steam tanks); transports table: The Kraken (Valiance Keep) and The Bravery (Auberdine); npc_text for Leesha Tannerby 26548 and Nayura 28650; DB spawns: Auberdine Sentinel x4, Steam Tank Engineer, Stormwind Cannoneer in the harbor; npc_text for Captain Paul Carver 29287 (The Assurance inundated with bugs)'),
(151903, 2, 1519, 1, 1, 0, 'King Varian Wrynn', 'Varian Wrynn was a boy when the orcs sacked Stormwind and King Llane, his father, was assassinated. Raised in exile in Lordaeron, he returned to rule the rebuilt city, married Tiffin and fathered a son, only to lose his queen when riots tore through the city streets. Then he vanished, leaving his kingdom to be ruled in his name by a regent.', 'warcraft.wiki.gg/wiki/Varian_Wrynn (youth, exile, Tiffin, abduction, Lo''Gosh, Onyxia unmasked, Wrathgate); npc_text 13593; quest 1250 description (king taken on his way to Theramore to meet Jaina); quest 13347 reward text; quest 13377 reward text (Peace? Useless)'),
(151904, 2, 1519, 2, 1, 0, 'Prince Anduin Wrynn', 'Prince Anduin Wrynn, son of King Varian and the late Queen Tiffin, was named for the hero Anduin Lothar and for his grandfather Llane. When his father vanished, Lady Katrana Prestor urged the council to crown the boy so that order might be kept, and Highlord Bolvar Fordragon was named regent to govern in his name. A quiet and thoughtful boy, he is gentle where his father is fierce.', 'warcraft.wiki.gg/wiki/Anduin_Wrynn (birth, naming, crowning under Bolvar''s regency at Prestor''s urging, kidnapping by Onyxia, personality, interest in the Light); DB spawn: Anduin Wrynn 1747 beside King Varian in the keep; npc_text 16641'),
(151905, 2, 1519, 3, 1, 0, 'Highlord Bolvar Fordragon', 'A paladin of the Silver Hand, Highlord Bolvar Fordragon was named regent of Stormwind for the boy king Anduin while King Varian was lost. For the long years of the regency he governed the kingdom in the young king''s name from the throne room of Stormwind Keep, and the noblewoman Lady Katrana Prestor stood close at his side, her counsel rarely far from his ear.', 'warcraft.wiki.gg/wiki/Bolvar_Fordragon (Silver Hand, regent, Drakefire Amulet, Valiance Expedition, Wrathgate); quest 6403 description and reward text (the Highlord a puppet; medallion held my mind and body captive); quest 12499 (Highlord Bolvar Fordragon at Fordragon Hold); quest 13347 description and completion text (This is my fault); quest 13370 description (Putress)'),
(151906, 2, 1519, 4, 1, 0, 'Master Mathias Shaw', 'Master Mathias Shaw leads SI:7, the kingdom''s intelligence service, from the barracks in Old Town. Few shady or underhanded dealings in the city escape his notice, and he likes to call himself the master of all assassins. His agents keep watch on the Defias in Westfall. When five of his best field agents went to the Eastern Plaguelands after the lost ranger lord Nathanos Marris, only one came back, to die in his sleep days later. With Ravenholdt refusing aid, Shaw has had to seek outside help to learn their fate.', 'npc_text 5994 (SI:7 headquarters); quest 393 description and reward text; quest 394 reward text (master of all assassins); quest 6182 and 6183 descriptions; quests 2359, 2360 (Agent Kearnen in Westfall); warcraft.wiki.gg/wiki/Mathias_Shaw'),
(151907, 2, 1519, 5, 1, 0, 'Archbishop Benedictus', 'Archbishop Benedictus leads the Church of the Holy Light from the Cathedral of Light in Cathedral Square. In his youth he studied under Archbishop Alonsus Faol, the benevolent patron who raised great sums to rebuild Stormwind after the Second War, and he helped the Church raise the Cathedral of Light that stands as a monument to his teacher. Benedictus succeeded his teacher at the head of the Church. From his cathedral he keeps watch on the Scourge even in distant lands: he has sent champions into Razorfen Downs to break the pact between the quilboar there and the lich Amnennar the Coldbringer. Tainted Eyes of Paleth, crafted long ago by human priests, are brought to him to be cleansed.', 'warcraft.wiki.gg/wiki/Archbishop_Benedictus (pupil of Faol, built the Cathedral, succeeded him); warcraft.wiki.gg/wiki/Alonsus_Faol; page_text 2291 (Faol plaque); quest 3636 description; quest 293 description and reward text'),
(151908, 2, 1519, 6, 1, 0, 'Baros Alexston', 'Baros Alexston, City Architect of Stormwind, keeps his office at City Hall in Cathedral Square. He grew up working his family''s farm in Westfall, a homestead since burned and seized by thieves. As a young man he was a member of the Stonemasons'' Guild, rebuilding the city after the war, and when the work was done he took the post of city architect and has stayed in Stormwind''s service ever since. Mathias Shaw of SI:7 owes him a favor.', 'quest 373 description and reward text; quest 389 description; quest 399 description; quest 393 description (Shaw owes me a favor); creature_template 1646 subname City Architect; warcraft.wiki.gg/wiki/Baros_Alexston (accepted the city architect position rather than join VanCleef)'),
(151909, 2, 1519, 7, 1, 0, 'Elling Trias', 'Elling Trias runs Trias'' Cheese in the Trade District with his wife Elaine and his son Ben, and will happily offer a taste of Trias cheddar or a block of Darnassian bleu. Those who know better come to him for something else. Behind the counter lies a quiet web of friends and contacts that reaches from Stormwind Keep to Darkshire and well beyond, and when the kingdom''s own agents cannot act, Trias can. He has little love for Mathias Shaw, who turns to him only when he must, and he prefers his justice swift and off the record. Those who trouble his friends, he says, rarely stay healthy for long.', 'quest 1242 request text (cheddar and Darnassian bleu); creature_template 483 Elaine Trias, 4981 Ben Trias; quests 1243, 1248, 1264, 2745 (contacts Backus, Mikhail, Samaul, Tyrion); quest 350 description and reward text; quest 2745 description; quest 434 completion text; warcraft.wiki.gg/wiki/Elling_Trias'),
(151910, 2, 1519, 8, 1, 0, 'Zardeth of the Black Claw', 'In the cellar of the Slaughtered Lamb tavern in the Mage Quarter, Zardeth of the Black Claw speaks for the warlocks of Stormwind, served by a demon named Zggi. Their gatherings have drawn the ire of Lord Baurles K. Wishock of the House of Nobles, who is lobbying for a full investigation, though Zardeth notes that the lord spends his nights upstairs running up a bill he never pays. Zardeth means to keep him preoccupied with a special Black Claw stout, brewed from a rare flower of Darkshire and a root from the Wetlands.', 'quests 335, 336, 397 (descriptions and reward texts); quest 24428 description and reward text (basement of the Slaughtered Lamb); creature_template 1733 Zggi, Zardeth''s Minion, creature type demon; warcraft.wiki.gg/wiki/Zardeth_of_the_Black_Claw (Slaughtered Lamb, Mage Quarter)'),
(151911, 3, 1519, 1, 1, 0, 'The Missing King', 'It begins with a whisper. Thomas, an altar boy, quietly seeks out capable strangers for Bishop DeLavey in Stormwind Keep, who confides that a diplomat sent to Theramore to meet Jaina Proudmoore never arrived. The Defias are involved somehow, and the matter must stay out of public view for as long as it can. DeLavey''s old friend Jorgen, a gruff fisherman in the Valley of Heroes, grudgingly passes the business to the cheesemonger Elling Trias, who puts his own contacts to work. The first is Watcher Backus of Darkshire, who recalls an odd gathering of Defias agents at Addle''s Stead in Duskwood a few weeks past, where something big seemed to have gone down.', 'quests 1274, 1241, 1242, 1243, 1244, 1245, 1246, 1447, 1247, 1248, 1249, 1250, 1264, 1265, 1266, 1324, 1267 (descriptions and reward texts); creature 4959 Jorgen spawned in the Valley of Heroes'),
(151912, 3, 1519, 2, 1, 0, 'VanCleef''s Last Plot', 'Even in death Edwin VanCleef had one more scheme. An unsent letter on his body, addressed to the City Architect Baros Alexston, led Baros to recall their days as Stonemasons, cheated by the nobles when the rebuilding was done, and to point toward Bazil Thredd, VanCleef''s lieutenant, held in the Stockade. If anyone knows what VanCleef planned, it is Thredd. But the Stockade is in uproar: Thredd''s riot has thrown open the cells, and Warden Thelwater trusts no one who comes asking after the prisoner.', 'quests 373, 389, 391, 392, 393, 350, 2745, 2746, 434, 394, 395, 396 (descriptions and reward texts); creature_text 1754, 1755, 7766, 8856; DB spawns: Lord Gregor Lescovar 1754 and Tyrion 7766 at Stormwind Keep'),
(151913, 3, 1519, 3, 1, 0, 'The Blightcaller', 'Nathanos Marris was the first and last of the human ranger lords, the only human ever allowed to train under the high elves, and a disciple of Sylvanas Windrunner. He was believed to have died defending Lordaeron, though his body was never found. When strange Forsaken activity was reported in the Eastern Plaguelands, SI:7 sent five of its best agents to investigate. One came back, able to utter only two words, Nathanos and Blightcaller, before dying in his sleep. Short of men, Mathias Shaw sends volunteers to the SI:7 operative Flint Shadowmore at Chillwind Camp, to search the east for the lost agents.', 'quests 6182, 6183, 6184, 6185, 6186, 6187 (descriptions and reward texts); creature_queststarter: 29611 King Varian Wrynn starts 6182'),
(151914, 3, 1519, 4, 1, 0, 'Dragons at Court', 'Through the years of the regency one noblewoman stood at the heart of the House of Wrynn''s affairs. Lady Katrana Prestor, a high noble and royal councilor, urged the council to crown the boy Anduin when his father was lost, and none stood closer to the regent, Highlord Bolvar Fordragon. Far to the east, the black dragon Nefarian, son of Deathwing, made himself lord of Blackrock Spire, with the Blackrock orcs at his command, while the soldiers of Morgan''s Vigil carry the fight to the black dragonflight''s doorstep.', 'quest 6403 description and reward text (Prestor is Onyxia, twin of Nefarian, the Highlord a puppet, Windsor''s sacrifice); quest 6501 description (lair in the Wyrmbog); warcraft.wiki.gg/wiki/Katrana_Prestor (councilor, Anduin crowned at her urging, Windsor killed, Anduin taken to her lair); quests 7781, 7782 and creature_text 14721; burning_steppes.json 4613 (Marshal Maxwell, Morgan''s Vigil); quest 24428; quest 7495'),
(151915, 3, 1519, 5, 1, 13, 'The Wrathgate and the King''s Wrath', 'When Bolvar Fordragon fell at the Wrathgate, the dragon queen Alexstrasza sent his shield home to King Varian with a message: all is not lost, and from the ashes of the fallen a force will rise to unite nations and purge the evil from the world. Varian brushed away a tear, called the loss his own fault, and took the message as a call to purge the Horde. At Jaina Proudmoore''s urging he has first allowed a diplomatic mission to Orgrimmar, and Jaina goes to hear the Warchief out, begging those with her to do nothing that might incite the Horde.', 'quests 13347, 13369, 13370, 13371, 13377 (descriptions and reward texts); creature_text 32346; npc_text 14131 (Jaina: avoid another war at all costs); warcraft.wiki.gg/wiki/Varian_Wrynn (Wrath section)'),
(151916, 3, 1519, 6, 1, 0, 'Where Kings Walk', 'When the Knights of the Ebon Blade broke from the Lich King, Highlord Darion Mograine sent those death knights who had once been heroes of the Alliance to Stormwind as envoys, bearing a letter from Tirion Fordring, for the order must find allies if it is to survive. Their welcome is bitter. Guards, some of whom lost their families to the Scourge, pelt them with rotten fruit, spit at them and cry murderer and monster as they make their way to the keep, and some call for a rope.', 'quest 13188 description, completion text and reward text; creature_text 68 and 1976 groups 2 to 5 (rotten fruit, spitting, Monster, My family was wiped out by the Scourge); warcraft.wiki.gg/wiki/Stormwind_City (Varian ordered death knights treated with respect after Tirion''s letter); spell_area 58530 (Alliance, quest 13165 done until 13188 done) and spell_script_names 58533 spell_chapter5_return_to_capital, which makes guards 68, 1756 and 1976 use text groups 2 to 5 on death knights');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(151900, 1, 0, 12, 'For years the king has been lost. Varian Wrynn vanished, his young son Anduin was crowned in his place, and Highlord Bolvar Fordragon governs the kingdom as regent from the throne room of Stormwind Keep.', 'warcraft.wiki.gg/wiki/Stormwind_City (regency of Bolvar for Anduin before Varian''s return in 3.0); quest 1250 reward text (his son being crowned)'),
(151900, 2, 13, 255, 'Those days are over. King Varian Wrynn has fought his way back across Azeroth after long years lost and sits on his throne again, his son beside him. Highlord Bolvar Fordragon has led the Alliance north to make war on the Lich King, and ships sail from the harbor below the city for Northrend.', 'npc_text 13593 (Varian: too long have I been gone... reclaim my throne); DB spawns: Varian 29611 and Anduin 1747 side by side in the keep; quest 12499 (Bolvar at Fordragon Hold); npc_text 12641 (the Kraken sails to Valiance Keep)'),
(151900, 3, 13, 255, 'Then came word from the Wrathgate. Highlord Bolvar Fordragon fell there, struck down with Alliance and Horde soldiers alike when the Forsaken traitor Putress loosed his plague, and only his shield came home. The city mourns its old regent, and its king''s grief has hardened into anger at the Horde.', 'quest 13347 description, completion and reward texts; quest 13370 description (Putress''s cowardly attack at the Wrath Gate)'),
(151901, 1, 8, 255, 'Word from beyond the Dark Portal tells a different story. Some of the heroes in stone still live: Khadgar stands in Shattrath City, Danath Trollbane holds Honor Hold in Hellfire Peninsula with the last of the expedition''s soldiers, and Kurdran Wildhammer leads the Wildhammer dwarves of Shadowmoon Valley.', 'DB: Khadgar 18166, Force Commander Danath Trollbane 16819, Kurdran Wildhammer 21330 spawned on map 530 (Outland); shattrath.json 370307, hellfire.json 348324, shadowmoon.json 352024'),
(151902, 1, 13, 255, 'The harbor was made for a new war. At the start of the war against the Lich King, Scourge forces struck at the city here, and King Varian Wrynn and Highlord Bolvar Fordragon directed the defense from atop the harbor walls. Now the port feeds that war. The steam-powered Kraken carries soldiers to Valiance Keep in the Borean Tundra, though the captain of the Assurance complains that his own ship, bound for Northrend, has somehow been overrun with bugs.', 'warcraft.wiki.gg/wiki/Stormwind_Harbor (added 3.0.2, Scourge attack, Varian and Bolvar on the walls); npc_text 12641 (Leesha Tannerby: the Kraken to Valiance Keep); npc_text 14056 (Captain Paul Carver: the Assurance inundated with bugs, unable to sail to Northrend)'),
(151903, 1, 0, 255, 'His vanishing was no accident. He had sailed in secret for Theramore to meet Lady Jaina Proudmoore, and the Defias Brotherhood, working with a partner more powerful than themselves, slipped their own man aboard the royal ship and took him.', 'quest 1250 description (the Defias took the king on his way to Theramore; working with someone; Hendel on the king''s ship)'),
(151903, 2, 0, 255, 'His absence left room for a monster. Lady Katrana Prestor, the councilor who had steered his court and urged his son''s crowning, was revealed as the black dragon Onyxia, brood of Deathwing, hiding in plain sight in his own keep.', 'quest 6403 description (Lady Prestor is Onyxia; even the Highlord a puppet); 6403 has no giver in the base DB, but mod-individual-progression restores it (starter 12580 Windsor, ender 1748 Bolvar); 7495 is its classic Onyxia head quest; 24428 is the 3.3.5 one; warcraft.wiki.gg/wiki/Varian_Wrynn (Onyxia unmasked)'),
(151903, 3, 13, 255, 'Far away, stripped of his memory, Varian had fought as a gladiator called Lo''Gosh before winning back his past, his name and his throne. Now he sits in Stormwind Keep once more, a fierce and grieving king who has been gone too long.', 'warcraft.wiki.gg/wiki/Varian_Wrynn (Lo''Gosh, return to the throne in patch 3.0.2); npc_text 13593 (too long have I been gone... reclaim my throne)'),
(151903, 4, 13, 255, 'The Wrathgate tore the old wounds open. When Bolvar Fordragon''s shield was laid before him, Varian brushed away a tear and called the loss his own fault. Then he swore to be the force that rises from the ashes, and to purge the evil of the Horde from the world.', 'quest 13347 completion and reward texts'),
(151903, 5, 13, 255, 'Even the hunt for Putress in the Undercity did not soften him. Peace with the Horde, he says, has gotten his people nowhere and cost them some of their greatest heroes, and he sends his champions back to Northrend to conquer it for their king.', 'quest 13377 reward text (Peace? Useless)'),
(151904, 1, 0, 255, 'The councilor who pressed for his crowning was no noblewoman. Lady Prestor was the black dragon Onyxia, and the boy king''s court had been a dragon''s game all along, the regent himself held captive by her magic.', 'quest 6403 description (Lady Prestor is Onyxia; even the Highlord a puppet); 6403 has no giver in the base DB, but mod-individual-progression restores it (starter 12580 Windsor, ender 1748 Bolvar); 7495 is its classic Onyxia head quest; 24428 is the 3.3.5 one'),
(151904, 2, 13, 255, 'His father has come home at last. The crown is King Varian''s once more, and the prince now stands at his side in Stormwind Keep, watching and listening as the king receives his champions.', 'DB spawn: Anduin Wrynn 1747 beside King Varian 29611 in the keep; npc_text 13593'),
(151904, 3, 13, 255, 'Her unmasking put the prince himself in peril. Onyxia seized the boy and carried him off to her lair, and he was saved only when a blade thrown by his father loosened her grip and Broll Bearmantle caught him as he fell from a great height.', 'warcraft.wiki.gg/wiki/Katrana_Prestor (World of Warcraft comic issue 12 onward, 2008: Onyxia takes Anduin to her lair; Lo''Gosh''s thrown knife loosens her grip; Broll catches him); warcraft.wiki.gg/wiki/Anduin_Wrynn (kidnapping by Onyxia at Varian''s return; Broll caught him)'),
(151905, 1, 0, 255, 'Her counsel was a chain. Only after Lady Prestor was unmasked as the dragon Onyxia did it become known that a medallion she had placed around his neck, the Dragon''s Eye, had held his mind and body captive, making the Highlord her puppet.', 'quest 6403 description (Lady Prestor is Onyxia; even the Highlord a puppet); 6403 has no giver in the base DB, but mod-individual-progression restores it (starter 12580 Windsor, ender 1748 Bolvar); 7495 is its classic Onyxia head quest; 24428 is the 3.3.5 one; quest 6403 reward text (this medallion is what held my mind and body captive)'),
(151905, 2, 13, 255, 'When King Varian returned to his throne, Bolvar took up the sword again. He led the Alliance north against the Lich King, and in the Dragonblight of Northrend the Alliance''s fortress bears his name: Fordragon Hold.', 'warcraft.wiki.gg/wiki/Bolvar_Fordragon (Valiance Expedition); quest 12499 (Highlord Bolvar Fordragon at Fordragon Hold)'),
(151905, 3, 13, 255, 'At Angrathar the Wrathgate the Forsaken traitor Putress loosed a plague upon Alliance and Horde alike, and the red dragonflight burned the field clean. Bolvar''s body was never found. His shield was carried home to the king, who blamed himself for the loss.', 'quest 13347 description and completion text (This is my fault); quest 13370 description (Putress)'),
(151906, 1, 0, 255, 'It was Shaw who recognized the quiet visitor to Bazil Thredd''s cell. The man had called himself Maelik, but Shaw knew him as the assassin Marzon, in the pay of Lord Gregor Lescovar. With so well connected a noble beyond the reach of any court, Shaw swallowed his pride and sent for help from Elling Trias.', 'quest 393 reward text; quest 350 description (I loathe to do so)'),
(151908, 1, 0, 255, 'The rebuilding ended badly. When the work was done the nobles refused to pay the masons, though some senior masons were offered posts in the government. Edwin VanCleef refused out of loyalty to all the Stonemasons, led a riot in the city, the unrest that cost Queen Tiffin her life, and left swearing revenge. When an unsent letter from VanCleef reached Baros after his death, Baros called him an idealist and a romantic consumed by revenge, yet admitted he could not entirely blame him.', 'quest 373 reward text; quest 389 description; warcraft.wiki.gg/wiki/Tiffin_Wrynn (killed in the Stonemason riots)'),
(151910, 1, 0, 255, 'The stout did its work. Lord Wishock took the brew from what he thought was a servant and settled in to enjoy it, and the warlocks of Stormwind have practiced their ways undisturbed ever since. Zardeth rewards his helpers through Zggi, who covets every gift but knows better than to betray his master.', 'quest 336 reward text; quest 397 description and reward text'),
(151910, 2, 13, 255, 'Of late even the head of the dragon Onyxia has found its way down to his cellar. Zardeth greets it with an oath by Nozdormu''s teeth, starts to ask how such a thing could be, then thinks better of the question and pays for the trophy.', 'quest 24428 description, completion and reward texts (basement of the Slaughtered Lamb)'),
(151911, 1, 0, 255, 'At Addle''s Stead lay a Defias docket, too detailed to be a ruse. Backus would not keep it, sure his superiors would hang him for knowing, but Trias read in it a plan the Brotherhood had worked hard to complete, and a name he knew: Fist, the Old Town brawler Dashel Stonefist.', 'quest 1245 description and reward text; quest 1246 description'),
(151911, 2, 0, 255, 'Dashel would not talk until he had been beaten in his own alley. Then he owned up to the meeting at Addle''s Stead. His part had ended when plan A failed, and the inside man for plan B had come out of Menethil Harbor, a man called Slim. The docket said nothing of where the captive was taken, so Trias sent word to an old contact, Mikhail, now tending bar in Menethil.', 'quests 1447, 1247 descriptions and reward texts; quest 1248 description'),
(151911, 3, 0, 255, 'In Mikhail''s tavern a stranger listening too closely tried to slip away and was caught: Tapoke Jahn, the man called Slim. He confessed that the Defias had taken no mere diplomat but the king of Stormwind himself, sailing in secret to meet Jaina Proudmoore, and that they had help from someone greater than they. His own part had been to get their man Hendel aboard the royal ship. Mikhail saw at once why the king''s young son had been crowned.', 'quest 1249 reward text; quest 1250 description and reward text'),
(151911, 4, 0, 255, 'Hendel proved to be a private of the Theramore garrison, one of the Kul Tiras marines who carouse in Menethil each payday. Commander Samaul found that Lady Proudmoore already knew of the plot. Cornered at his post in Dustwallow Marsh, Hendel turned on his accuser, was beaten and taken back to Theramore for questioning, and Jaina quietly thanked those who had uncovered the plot.', 'quests 1264, 1265, 1266, 1324 descriptions and reward texts; quest 1267 reward text (auto-complete, so QUEST_DONE)'),
(151912, 1, 0, 255, 'Thredd died amid his riot, and the warden had more to tell. For years no one had visited the prisoner, but a few months ago a quiet stranger began calling once or twice a week, his papers always in order, his name given as Maelik.', 'quest 391 reward text; quest 392 description'),
(151912, 2, 0, 255, 'Mathias Shaw knew the description. Maelik was one mask among many worn by the assassin Marzon, now in the pay of Lord Gregor Lescovar, a noble of shady reputation. With VanCleef and Thredd dead, no court would touch so well connected a lord, so Shaw reluctantly sent word to Elling Trias.', 'quest 393 reward text; quest 350 description'),
(151912, 3, 0, 255, 'Trias''s friend Tyrion, a gnome who had watched Lescovar for weeks on suspicion of ties to the Twilight''s Hammer, sent his disguised Spybot past the guards and fed Marzon word that it was time to meet. Lescovar dismissed his guards to wait in the castle garden. Once their talk of the Defias was overheard, lord and assassin were both cut down before the guards returned.', 'quests 2745, 2746 (request text: Twilight''s Hammer leads), 434 descriptions and texts; creature_text 1754, 1755, 7766, 8856'),
(151912, 4, 0, 255, 'Shaw advised that no one ever learn whose hand had slain Lescovar, nor hear the name of Trias. Baros, grateful to be spared VanCleef''s revenge, wrote a report on the Brotherhood for the throne, and its bearer was commended for sparing the kingdom considerable harm.', 'quest 395 description and reward text; quest 396 description and reward text'),
(151913, 1, 0, 255, 'The insignias of the lost agents were found in the east, and Flint could name his dead: Rutger, Fredo, Turyen. What came with them drained the blood from his face. The Blightcaller was Nathanos himself, the noble ranger lord now a ruthless agent of the Forsaken, and Stormwind Keep had to be told at once.', 'quest 6185 reward text; quest 6186 description'),
(151913, 2, 0, 255, 'The truth struck Stormwind Keep like a blow. Nathanos, a tactical genius behind a decade of Alliance victories, had become the champion of the Banshee Queen. Order, the throne declared, must be restored: an army was to gather and march on the Plaguelands to destroy the Blightcaller, though the Horde would defend him with their lives.', 'quest 6186 reward text; quest 6187 description and objectives'),
(151913, 3, 0, 255, 'The army went east and struck the Blightcaller down, and the keep took no joy in it. Stormwind''s ruler mourned that humankind seems cursed to lose its greatest warriors, its noblest heroes and its most gifted scholars, and told the victors that wherever Nathanos Marris truly was, he smiled down on them.', 'quest 6187 reward text'),
(151914, 1, 0, 255, 'Lady Prestor was Onyxia, brood of Deathwing and twin of Nefarian, and a medallion she had placed upon Bolvar held him captive, a puppet on her strings. Her masquerade ended in Stormwind Keep at the cost of Marshal Reginald Windsor''s life, and she fled to her lair in the Wyrmbog of Dustwallow Marsh.', 'quest 6403 description (Lady Prestor is Onyxia; even the Highlord a puppet); 6403 has no giver in the base DB, but mod-individual-progression restores it (starter 12580 Windsor, ender 1748 Bolvar); 7495 is its classic Onyxia head quest; 24428 is the 3.3.5 one; quest 6403 reward text (Windsor''s sacrifice; the medallion); quest 6501 description (lair in the Wyrmbog); warcraft.wiki.gg/wiki/Katrana_Prestor'),
(151914, 2, 0, 255, 'Nefarian met his end at the hands of the Alliance. When his head was carried back to Stormwind, the keep hailed a victory the like of which the Alliance had not known in years, if ever, and Field Marshal Afrasiabi called the city to rally around its champions in the Valley of Heroes.', 'quest 7781 reward text; quest 7782; creature_text 14721'),
(151914, 3, 0, 255, 'In time the brood mother herself was slain in her lair. The dragon who had worn a councilor''s face and held a regent on a chain would trouble the court of Stormwind no more, and the honor of the kingdom was restored.', 'quest 24428 description (the brood mother lies dead); quest 7495 description and reward text (justice meted, the honor of Stormwind restored)'),
(151915, 1, 13, 255, 'Thrall received her in Grommash Hold and called off his guards. The Horde, he swore, had no part in Putress''s cowardly attack and had lost heroes of its own to the betrayal. It would do all it could to bring the traitors to justice and avoid conflict with the Alliance, but it would defend itself if provoked. And he let one thing more be known: the Horde had lost the Undercity.', 'quest 13370 description; creature_text 32363 (Kor''kron, stand down; the Horde has lost the Undercity); creature_text 32346'),
(151915, 2, 13, 255, 'Varian seized the moment. If the Horde had lost the Undercity, the time to strike was now. Broll Bearmantle and Valeera Sanguinar already waited outside the ruins, Jaina opened a portal from Stormwind Keep, and the king led the Alliance in to bring Putress to justice and take the Ruins of Lordaeron for the Alliance.', 'quest 13370 reward text; quest 13371 description; quest 13377 description'),
(151915, 3, 13, 255, 'He came home convinced that peace had won his people nothing. For too long, he declared, the Horde had been left unchecked, its lands allowed to prosper while it plotted the Alliance''s ruin. Peace had cost them some of their greatest heroes, and he sent his champions back to Northrend to conquer it for their king.', 'quest 13377 reward text'),
(151916, 1, 0, 255, 'King Varian declared that only the word of Tirion, one of the greatest paladins ever to live, kept the envoy from becoming a stain upon his floor. Yet he honored his old friend''s letter. Blood and honor, he answered, and he pledged that Stormwind would fight alongside the Ebon Blade against the Scourge and the Lich King.', 'quest 13188 reward text');
